    for (const [field, count] of [['cpuBackings', 'cpuBackingCount'], ['gpuAttributes', 'gpuAttributeCount'], ['textures', 'gpuTextureCount'], ['canvases', 'canvasCount']]) assert.equal(storage[field].size, oracle[count]);
