    gpuTextureBytes: 0, canvasBackingEstimateBytes: 0, customPreflight: custom(), customActual: custom(), hostReservationBytes: 0,
    semantic: { selectedRows: 0, dimmedRows: 0, labelRows: 0, labelTextUnits: 0, dashRows: 0, dashValues: 0, customRows: 0 },
