function independentPresentationFit(positions, width, height) {
  const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (let index = 0; index < positions.length; index++) { const axis = index % 3; lo[axis] = Math.min(lo[axis], positions[index]); hi[axis] = Math.max(hi[axis], positions[index]); }
  if (!positions.length) return { yaw: 0, pitch: 0, distance: 500, target: { x: 0, y: 0, z: 0 } };
  const radius = Math.max(1, Math.hypot(hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2]) / 2);
  const w = Math.max(1, width), h = Math.max(1, height), padding = Math.min(24, Math.min(w, h) * 0.45);
  const angle = Math.atan(Math.tan(Math.PI / 8) * Math.min((w - 2 * padding) / h, (h - 2 * padding) / h));
  return { yaw: 0, pitch: 0, distance: radius / Math.sin(angle), target: { x: (lo[0] + hi[0]) / 2, y: (lo[1] + hi[1]) / 2, z: (lo[2] + hi[2]) / 2 } };
}

