const reservationMiB = 1024 * 1024;
const reservationBudgetError = error => error instanceof RangeError && error.reason === 'budget';

function reservationPolicy(nodes, customRows, faces, ordinaryPrimitives, views) {
  if (customRows === 0) return { cpuBytes: 0, gpuBytes: 0, accountedBytes: 0 };
  const cpuBytes = (96 + 200 * views) * faces + 32 * customRows
    + (16 + 5 * views) * nodes + 8 * views * ordinaryPrimitives + 4 * views;
  const gpuBytes = 160 * views * faces;
  return { cpuBytes, gpuBytes, accountedBytes: cpuBytes + gpuBytes };
}

function reservationMesh(faces) {
  const positions = new Float32Array(faces * 9), normals = new Float32Array(faces * 3);
  for (let face = 0; face < faces; face++) {
    positions.set([-0.5, -0.5, 0, 0.5, -0.5, 0, 0, 0.5, 0], face * 9);
    normals[face * 3 + 2] = 1;
  }
  return { positions, normals, color: [1, 1, 1, 1] };
}

function reservationFixture({ nodes, customRows = 0, faces = 0, ordinaryPrimitives = nodes,
  firstOwner = true, allNullMeshes = false }) {
  // Each self-loop contributes exactly 16 primitives. Remaining edges are ordinary
  // non-loop straight edges contributing one. This keeps admitted logical edges below
  // 1,000,000 without changing the independently specified expanded primitive count.
  const primitives = ordinaryPrimitives - nodes, loops = Math.floor(primitives / 16), straight = primitives % 16;
  assert.ok(Number.isSafeInteger(primitives) && primitives >= 0);
  assert.ok(nodes >= 2 || straight === 0);
  const source = new Uint32Array(loops + straight), target = new Uint32Array(loops + straight);
  for (let edge = loops; edge < target.length; edge++) target[edge] = 1;
  const spatialAppearance = { sizeUnits: 'world', dimmedOpacity: 1 };
  if (customRows || allNullMeshes) {
    const nodeMeshes = new Array(nodes).fill(null);
    let remaining = faces;
    for (let row = 0; row < customRows; row++) {
      const count = Math.min(64, remaining - (customRows - row - 1));
      assert.ok(count >= 1 && count <= 64);
      nodeMeshes[row] = reservationMesh(count); remaining -= count;
    }
    assert.equal(remaining, 0); spatialAppearance.nodeMeshes = nodeMeshes;
  }
  const raw = { nodeCount: nodes, source, target, positions: new Float32Array(nodes * 3),
    pinned: new Uint8Array(nodes), spatialAppearance, nodeLabels: 'none', withEdgeLabels: false, particlesPerEdge: 0 };
  const prepared = drainPresentationChild(createGraphDataPreparationWork(raw));
  const presentation = drainPresentationChild(createGraphPresentationSnapshotWork({
    inheritedStyle: resolveLyra3dStyle(), inheritedState: emptyState(),
    presentation: { style: { palette: ['#ffffff'], foreground: '#ffffff', muted: '#000000', accent: '#ffffff', focus: '#ffffff' },
      state: emptyState() },
  }));
  const { input: template } = preparePresentationFixture('ordinaryEmpty', firstOwner);
  return { ...template, prepared, presentation, firstOwner, previousStorage: undefined };
}

function reservationBeforeSceneAllocation(input, expectedError) {
  const sentinel = new Error('first scene position allocation'), OriginalFloat32Array = Float32Array;
  let allocations = 0;
  const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'Float32Array');
  const GuardedFloat32Array = new Proxy(OriginalFloat32Array, { construct(target, args, newTarget) {
    const argument = args[0];
    const count = typeof argument === 'number' ? argument
      : ArrayBuffer.isView(argument) || Array.isArray(argument) ? argument.length
        : argument instanceof ArrayBuffer ? argument.byteLength / 4 : 0;
    if (count > 0) {
      allocations++;
      assert.equal(count, input.prepared.data.nodeCount * 3, 'first scene allocation is the shared node position backing');
      throw sentinel;
    }
    return Reflect.construct(target, args, newTarget);
  } });
  withProperty(globalThis, 'Float32Array', { ...descriptor, value: GuardedFloat32Array }, () => {
    let work;
    try {
      assert.throws(() => {
        work = createGraphPresentationWork(input);
        drainPresentationChild(work);
      }, expectedError ?? (error => error === sentinel));
      assert.ok(work, 'factory remains inert until the first step');
      assert.equal(allocations, expectedError ? 0 : 1);
      assert.throws(() => work.step(1), { name: 'InvalidStateError' });
    } finally { work?.dispose(); }
  });
}

function reservationSyntheticPrevious(accountedBytes) {
  const previous = emptyPresentationStorage();
  // Deliberately synthetic accounting input: this is not a claim that a qualified
  // current graph can attain 96 MiB under the individual generation ceilings.
  const policy = { cpuBytes: accountedBytes, gpuBytes: 0, accountedBytes };
  return { ...previous, customPreflight: { ...policy }, customActual: { ...policy },
    admissionPeakCustomBytes: accountedBytes, peak: { ...previous.peak, customAccountedBytes: accountedBytes } };
}

test('zero custom rows retain zero reservation for single and dual owners including admitted all-null meshes', () => {
  for (const firstOwner of [false, true]) for (const allNullMeshes of [false, true]) {
    const input = reservationFixture({ nodes: 3, firstOwner, allNullMeshes });
    const work = createGraphPresentationWork(input); let candidate;
    try {
      candidate = drainPresentationChild(work);
      const record = readGraphPresentationCandidate(candidate), zero = { cpuBytes: 0, gpuBytes: 0, accountedBytes: 0 };
      assert.deepEqual(record.storage.customPreflight, zero); assert.deepEqual(record.storage.customActual, zero);
      assert.equal(record.storage.hostReservationBytes, 0);
    } finally { work.dispose(); if (candidate) prepareGraphPresentationRetirement(candidate).dispose(); }
  }
});

test('dual custom CPU reservation accepts exactly 32 MiB and rejects one additional straight primitive before allocation', () => {
  const exact = reservationPolicy(100004, 1, 1, 1934612, 2);
  assert.deepEqual(exact, { cpuBytes: 33554432, gpuBytes: 320, accountedBytes: 33554752 });
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 100004, customRows: 1, faces: 1, ordinaryPrimitives: 1934612 }));
  assert.equal(reservationPolicy(100004, 1, 1, 1934613, 2).cpuBytes, exact.cpuBytes + 16);
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 100004, customRows: 1, faces: 1, ordinaryPrimitives: 1934613 }), reservationBudgetError);
});

test('single custom CPU reservation accepts exactly 32 MiB and rejects one additional straight primitive before allocation', () => {
  const exact = reservationPolicy(199996, 1024, 65536, 1240386, 1);
  assert.deepEqual(exact, { cpuBytes: 33554432, gpuBytes: 10485760, accountedBytes: 44040192 });
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 199996, customRows: 1024, faces: 65536,
    ordinaryPrimitives: 1240386, firstOwner: false }));
  assert.equal(reservationPolicy(199996, 1024, 65536, 1240387, 1).cpuBytes, exact.cpuBytes + 8);
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 199996, customRows: 1024, faces: 65536,
    ordinaryPrimitives: 1240387, firstOwner: false }), reservationBudgetError);
});

test('dual custom GPU reservation respects the adjacent representable values around 16 MiB', () => {
  const below = reservationPolicy(820, 820, 52428, 820, 2), above = reservationPolicy(820, 820, 52429, 820, 2);
  assert.deepEqual(below, { cpuBytes: 26064976, gpuBytes: 16776960, accountedBytes: 42841936 });
  assert.deepEqual(above, { cpuBytes: 26065472, gpuBytes: 16777280, accountedBytes: 42842752 });
  assert.equal(16 * reservationMiB - below.gpuBytes, 256); assert.equal(above.gpuBytes - 16 * reservationMiB, 64);
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 820, customRows: 820, faces: 52428 }));
  reservationBeforeSceneAllocation(reservationFixture({ nodes: 820, customRows: 820, faces: 52429 }), reservationBudgetError);
});

test('conservative custom preflight rejects before allocation even when opaque world-sized actual output would fit', () => {
  const input = reservationFixture({ nodes: 100004, customRows: 1, faces: 1, ordinaryPrimitives: 1934613 });
  // This fixture has opaque paint and world-sized loops: no sort keys, CSS-loop
  // offsets or changed custom-pick scratch are needed by the actual output.
  const actualCpu = (96 + 180 * 2) * 1 + 32 * 1 + (16 + 5 * 2) * 100004 + 4 * 2;
  assert.equal(actualCpu, 2600600); assert.ok(actualCpu < 32 * reservationMiB);
  assert.equal(reservationPolicy(100004, 1, 1, 1934613, 2).cpuBytes, 33554448);
  reservationBeforeSceneAllocation(input, reservationBudgetError);
});

test('synthetic current-plus-candidate accounting enforces 96 MiB and rejects unsafe scalar arithmetic', () => {
  const policy = reservationPolicy(2, 1, 1, 2, 2); assert.equal(policy.accountedBytes, 940);
  const previousAtBoundary = 96 * reservationMiB - policy.accountedBytes;
  const exact = reservationFixture({ nodes: 2, customRows: 1, faces: 1 });
  exact.previousStorage = reservationSyntheticPrevious(previousAtBoundary);
  reservationBeforeSceneAllocation(exact);
  const over = reservationFixture({ nodes: 2, customRows: 1, faces: 1 });
  over.previousStorage = reservationSyntheticPrevious(previousAtBoundary + 1);
  reservationBeforeSceneAllocation(over, reservationBudgetError);
  for (const value of [-1, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    const invalid = reservationFixture({ nodes: 2, customRows: 1, faces: 1 });
    invalid.previousStorage = reservationSyntheticPrevious(value);
    reservationBeforeSceneAllocation(invalid, error => error instanceof RangeError);
  }
  const sumOverflow = reservationFixture({ nodes: 2, customRows: 1, faces: 1 });
  sumOverflow.previousStorage = reservationSyntheticPrevious(Number.MAX_SAFE_INTEGER);
  reservationBeforeSceneAllocation(sumOverflow, reservationBudgetError);
});
